    record SessionSummary(String sessionId, String workingDirectory, Optional<String> name,
                          Instant updatedAt, long revision) {
        public SessionSummary {
            if (sessionId == null || sessionId.isBlank() || workingDirectory == null
                    || workingDirectory.isBlank() || updatedAt == null || revision < 0) {
                throw new IllegalArgumentException("invalid Session summary");
            }
            name = name == null ? Optional.empty() : name;
        }

        public static SessionSummary from(SessionDocument document) {
            Instant updated = document.log().stream().map(mutation -> mutation instanceof SessionDocument.EntryMutation entry
                    ? entry.entry().createdAt() : mutation instanceof SessionDocument.RecordMutation record
                    ? record.record().createdAt() : document.metadata().createdAt())
                    .max(Instant::compareTo).orElse(document.metadata().createdAt());
            return new SessionSummary(document.metadata().sessionId(), document.workingDirectory(),
                    document.name(), updated, document.revision());
        }
    }

    @Override
    default void close() {}
}
